func:
// Start: nach jedem Neustart von Node-RED
// ─ Zweck: Startzeit merken, Einstellungen prüfen, Neustart ins Log schreiben.
// ─ Eingang: Inject einmal 2 s nach dem Start
// ─ Ausgang 1: msg.log (info, bei fehlenden Pflichtwerten zusätzlich eine Warnung mit melden 'konfig')
// ─ Kontext: global.radler_start

global.set('radler_start', Date.now());

const MODI = ['EMS_MODUS', 'WB_MODUS', 'WP_MODUS', 'WL_MODUS', 'HA_MODUS', 'WB_PV_MODUS'];
const QUELLEN = ['PV_QUELLE', 'BKW_QUELLE', 'NETZ_QUELLE', 'BATTERIE_QUELLE', 'WALLBOX_QUELLE', 'AUTO_QUELLE', 'WP_QUELLE'];
const modi = MODI.map(n => `${n}=${env.get(n) || '(Standard)'}`).join(', ');
const quellen = QUELLEN.map(n => `${n}=${env.get(n) || (n === 'BKW_QUELLE' ? 'aus' : 'simulator')}`).join(', ');

const msgs = [{ log: { stufe: 'info', bereich: 'system', text: 'Node-RED gestartet', daten: { modi, quellen } } }];

// Ohne Standort gibt es weder Wetter noch PV-Prognose für den richtigen Ort
const fehlend = ['STANDORT_LAT', 'STANDORT_LON', 'PV_FLAECHEN'].filter(n => !env.get(n));
if (fehlend.length) {
    msgs.push({ log: { stufe: 'warnung', bereich: 'system', melden: 'konfig',
        text: 'Einstellungen fehlen in secrets.env (Standardwerte aktiv): ' + fehlend.join(', ') } });
}
const echte = QUELLEN.filter(n => env.get(n) === 'geraet');
node.status({ fill: 'green', shape: 'dot',
    text: echte.length ? 'echte Geräte: ' + echte.join(', ') : 'alle Geräte im Simulator' });
return [msgs];

// Messwerte → Prozessabbild und InfluxDB (Bucket "geraete")
// ─ Zweck: einzige Stelle, an der Messwerte ins Prozessabbild (global.abbild) und in die InfluxDB gehen (R1).
// ─ Eingang: msg.geraet ('pv', 'netz', 'batterie', 'wallbox', 'auto', 'wp' …),
//            msg.payload = { feld: wert, … } (Feldnamen mit Einheit als Endung: leistung_W, soc_pct, raum_C),
//            msg.quelle ('simulator', 'geraet', 'manuell' …), optional msg.zeit (ms).
// ─ Ausgang 1: msg.payload = InfluxDB-Punkte für den Batch-Knoten.
// ─ Kontext: global.abbild = { 'geraet.feld': { wert, einheit, zeit, quelle } }
// Kommt ein Netzwert, rechnet der Knoten die Hausbilanz (Messreihe "haus"):
//   verbrauch = Netzbezug + PV + Balkonkraftwerk + Batterie-Entladung (alle Vorzeichen siehe docs/architektur.md)

const EINHEITEN = [['_kWh', 'kWh'], ['_Wh', 'Wh'], ['_W', 'W'], ['_pct', '%'], ['_C', '°C'], ['_K', 'K'], ['_A', 'A']];
function einheit(feld) {
    for (const [endung, e] of EINHEITEN) if (feld.endsWith(endung)) return e;
    return '';
}

const geraet = msg.geraet;
if (!geraet || !msg.payload || typeof msg.payload !== 'object') {
    node.warn('Messwert ohne msg.geraet oder msg.payload verworfen');
    return null;
}
const zeit = msg.zeit || Date.now();
const quelle = msg.quelle || 'unbekannt';
const abbild = global.get('abbild') || {};

const fields = {};
for (const [feld, w] of Object.entries(msg.payload)) {
    if (w === null || w === undefined) continue;
    if (typeof w === 'number' && !isFinite(w)) continue;
    abbild[geraet + '.' + feld] = { wert: w, einheit: einheit(feld), zeit, quelle };
    if (typeof w === 'boolean') fields[feld] = w ? 1 : 0;
    else if (typeof w === 'number' || typeof w === 'string') fields[feld] = w;
}
if (!Object.keys(fields).length) return null;

const punkte = [{ measurement: geraet, tags: { quelle }, fields, timestamp: new Date(zeit) }];

if (geraet === 'netz' && typeof fields.bezug_W === 'number') {
    // Hausbilanz: Werte höchstens 60 s alt, fehlende Geräte zählen als 0
    const g = s => { const e = abbild[s]; return e && zeit - e.zeit <= 60000 && typeof e.wert === 'number' ? e.wert : 0; };
    const verbrauch = Math.max(0, fields.bezug_W + g('pv.leistung_W') + g('bkw.leistung_W') + g('batterie.leistung_W'));
    const ohneAuto = Math.max(0, verbrauch - g('wallbox.leistung_W'));
    const haus = {
        verbrauch_W: Math.round(verbrauch),
        ohne_auto_W: Math.round(ohneAuto),
        grundlast_W: Math.round(Math.max(0, ohneAuto - g('wp.leistung_W'))),
    };
    for (const [feld, w] of Object.entries(haus)) abbild['haus.' + feld] = { wert: w, einheit: 'W', zeit, quelle: 'bilanz' };
    punkte.push({ measurement: 'haus', tags: { quelle: 'bilanz' }, fields: haus, timestamp: new Date(zeit) });
}

global.set('abbild', abbild);
const n = (context.get('n') || 0) + 1;
context.set('n', n);
node.status({ fill: 'green', shape: 'dot', text: `${geraet} (${quelle}) · ${Object.keys(abbild).length} Signale · ${n} Meldungen` });
msg.payload = punkte;
return msg;

// Logeintrag erzeugen (R2): ein Log für alles
// ─ Eingang: msg.log = { stufe: 'fehler'|'warnung'|'info', bereich, text, daten?, melden? }
//            melden: true oder eine Art aus dem Meldekatalog ('zusage', 'geraet', 'wallbox' …)
// ─ Ausgang 1: Zeile für die Logdatei (msg.filename, msg.payload = JSON)
// ─ Ausgang 2: Fehler und Warnungen → InfluxDB (Bucket "ems", Messreihe "ems_log")
// ─ Ausgang 3: Einträge mit melden → Meldung prüfen
// ─ Umgebung: LOG_VERZEICHNIS (Standard /home/pi/radler-ems/log)

const STUFEN = ['fehler', 'warnung', 'info'];
const l = msg.log || {};
const stufe = STUFEN.includes(l.stufe) ? l.stufe : 'info';
const jetzt = new Date();
const eintrag = { zeit: jetzt.toISOString(), stufe, bereich: l.bereich || 'system', text: String(l.text || '') };
if (l.daten !== undefined) eintrag.daten = l.daten;
if (l.melden) eintrag.melden = l.melden;

// Datum in deutscher Zeit, eine Datei je Tag
const tag = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin' }).format(jetzt);
const verzeichnis = (env.get('LOG_VERZEICHNIS') || '/home/pi/radler-ems/log').replace(/\/$/, '');
const datei = { filename: `${verzeichnis}/radler-ems-${tag}.log`, payload: JSON.stringify(eintrag) };

const influx = stufe === 'info' ? null : {
    payload: [{ measurement: 'ems_log', tags: { stufe, bereich: eintrag.bereich }, fields: { text: eintrag.text }, timestamp: jetzt }],
};
const meldung = l.melden ? { meldung: eintrag } : null;

const zaehler = context.get('zaehler') || { fehler: 0, warnung: 0, info: 0 };
zaehler[stufe]++;
context.set('zaehler', zaehler);
node.status({
    fill: stufe === 'fehler' ? 'red' : stufe === 'warnung' ? 'yellow' : 'green', shape: 'dot',
    text: `${zaehler.fehler} Fehler, ${zaehler.warnung} Warnungen, ${zaehler.info} Info · ${eintrag.text.slice(0, 50)}`,
});
return [datei, influx, meldung];

// Meldung prüfen (R5): Katalog, Sperrzeit, Nachtruhe, Versand über ntfy
// ─ Eingang: msg.meldung = Logeintrag mit melden (vom Knoten "Logeintrag erzeugen")
// ─ Ausgang 1: HTTP-Anfrage an ntfy (JSON), nur wenn NTFY_TOPIC gesetzt ist
// ─ Ausgang 2: msg.log (Info: gesendet / wartet / kein Kanal) → Log, ohne melden (keine Schleife)
// ─ Umgebung: NTFY_TOPIC, NTFY_SERVER (Standard https://ntfy.sh), MELDUNG_RUHE_VON (22), MELDUNG_RUHE_BIS (7)
// ─ Kontext: context.gesendet (Sperrzeiten), global.meldung_nacht (nachts zurückgehalten, für den Tagesbericht)

const KATALOG = {
    zusage:       { titel: 'Zusage in Gefahr', sperre_min: 60,  nachts: true,  prio: 5 },
    geraet:       { titel: 'Gerät',            sperre_min: 60,  nachts: true,  prio: 4 },
    befehl:       { titel: 'Befehl abgelehnt', sperre_min: 60,  nachts: false, prio: 4 },
    konfig:       { titel: 'Einstellung',      sperre_min: 360, nachts: false, prio: 3 },
    wallbox:      { titel: 'Wallbox',          sperre_min: 0,   nachts: true,  prio: 3 },
    tagesbericht: { titel: 'Tagesbericht',     sperre_min: 0,   nachts: true,  prio: 2 },
    sonst:        { titel: 'Radler-EMS',       sperre_min: 60,  nachts: false, prio: 3 },
};

function zahl(name, std) { const n = parseFloat(env.get(name)); return isNaN(n) ? std : n; }
function stundeBerlin(t) {
    return parseInt(new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', hour: 'numeric', hourCycle: 'h23' }).format(t), 10);
}

const e = msg.meldung;
if (!e || !e.text) return null;
const art = typeof e.melden === 'string' && KATALOG[e.melden] ? e.melden : 'sonst';
const k = KATALOG[art];
const jetzt = Date.now();

// Sperrzeit: gleiche Meldung (Zahlen zählen nicht als Unterschied) höchstens einmal je Sperrzeit
const schluessel = art + ':' + e.text.replace(/[-+]?\d+([.,]\d+)?/g, '#');
const gesendet = context.get('gesendet') || {};
for (const s of Object.keys(gesendet)) if (jetzt - gesendet[s] > 86400000) delete gesendet[s];
if (k.sperre_min > 0 && gesendet[schluessel] && jetzt - gesendet[schluessel] < k.sperre_min * 60000) {
    node.status({ fill: 'grey', shape: 'ring', text: 'gesperrt: ' + e.text.slice(0, 40) });
    return null;
}

// Nachtruhe: nur Fehler und Arten mit nachts: true gehen raus
const h = stundeBerlin(jetzt);
const von = zahl('MELDUNG_RUHE_VON', 22), bis = zahl('MELDUNG_RUHE_BIS', 7);
const ruhe = von > bis ? (h >= von || h < bis) : (h >= von && h < bis);
if (ruhe && !k.nachts && e.stufe !== 'fehler') {
    const nacht = global.get('meldung_nacht') || [];
    if (!nacht.some(x => x.schluessel === schluessel)) nacht.push({ zeit: e.zeit, text: e.text, schluessel });
    global.set('meldung_nacht', nacht.slice(-50));
    node.status({ fill: 'blue', shape: 'ring', text: 'Nachtruhe, wartet: ' + e.text.slice(0, 40) });
    return [null, { log: { stufe: 'info', bereich: 'meldung', text: 'Meldung wartet (Nachtruhe): ' + e.text } }];
}

gesendet[schluessel] = jetzt;
context.set('gesendet', gesendet);

const topic = env.get('NTFY_TOPIC');
if (!topic) {
    node.status({ fill: 'grey', shape: 'dot', text: 'kein Kanal (NTFY_TOPIC leer): ' + e.text.slice(0, 40) });
    return [null, { log: { stufe: 'info', bereich: 'meldung', text: 'Meldung ohne Kanal: ' + e.text } }];
}
const server = (env.get('NTFY_SERVER') || 'https://ntfy.sh').replace(/\/$/, '');
node.status({ fill: 'green', shape: 'dot', text: 'gesendet: ' + e.text.slice(0, 40) });
return [
    {
        url: server, method: 'POST', headers: { 'Content-Type': 'application/json' },
        payload: JSON.stringify({ topic, title: 'Radler-EMS: ' + k.titel, message: e.text, priority: k.prio }),
    },
    { log: { stufe: 'info', bereich: 'meldung', text: `Meldung gesendet (${art}): ${e.text}` } },
];

// Warnungen und Fehler (Node-RED-Log) → Log
// ─ Zweck: holt alle 5 s, was der Logger aus settings.js (deploy/settings-radler.js) gesammelt hat,
//          damit node.warn/node.error aller Knoten im Log landen, ohne die Knoten zu ändern (R2.3).
// ─ Eingang: Inject alle 5 s. Kontext: global.radlerLogPuffer (Array, von settings.js angelegt)
// ─ Ausgang 1: je Eintrag eine Nachricht msg.log (Link → Log)
// Knoten des Log-Bereichs selbst (IDs beginnen mit "log-") werden übergangen, sonst gäbe es eine Schleife.

const puffer = global.get('radlerLogPuffer');
if (!Array.isArray(puffer)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'kein Puffer: Zusatz in settings.js fehlt' });
    return null;
}
const neu = puffer.splice(0, puffer.length);
const msgs = neu
    .filter(e => !(e.id || '').startsWith('log-'))
    .map(e => ({
        log: {
            stufe: e.level <= 20 ? 'fehler' : 'warnung',
            bereich: 'node-red',
            text: `${e.name || e.typ || e.id}: ${typeof e.text === 'string' ? e.text : JSON.stringify(e.text)}`.slice(0, 500),
            daten: { id: e.id, tab: e.z },
        },
    }));
const gesamt = (context.get('gesamt') || 0) + msgs.length;
context.set('gesamt', gesamt);
node.status({ fill: 'green', shape: 'dot', text: `${gesamt} übernommen` });
return msgs.length ? [msgs] : null;

// Geräte-Wächter: meldet Geräte, die keine Werte mehr liefern, und ihre Rückkehr
// ─ Eingang: Inject jede Minute. Kontext: global.abbild
// ─ Ausgang 1: msg.log (fehler mit melden 'geraet' bzw. info bei Rückkehr) → Log
// ─ Umgebung: GERAET_OFFLINE_MIN (15), <GERÄT>_QUELLE (aus = nicht überwachen; BKW_QUELLE ist ohne Angabe aus)

const SIGNALE = [
    // [Signal, Name, Umgebungsvariable der Quelle, Grenze in Minuten (null = GERAET_OFFLINE_MIN)]
    ['pv.leistung_W', 'PV-Wechselrichter', 'PV_QUELLE', null],
    ['bkw.leistung_W', 'Balkonkraftwerk', 'BKW_QUELLE', null],
    ['netz.bezug_W', 'Netzzähler', 'NETZ_QUELLE', null],
    ['batterie.soc_pct', 'PV-Batterie', 'BATTERIE_QUELLE', null],
    ['wallbox.status', 'Wallbox', 'WALLBOX_QUELLE', null],
    ['wp.status', 'Wärmepumpe', 'WP_QUELLE', null],
    ['markt.preise', 'Strompreise', null, 180],
    ['prognose.pv', 'PV-Prognose', null, 180],
];

const jetzt = Date.now();
const abbild = global.get('abbild') || {};
const grenzeStd = parseFloat(env.get('GERAET_OFFLINE_MIN')) || 15;
const start = global.get('radler_start') || jetzt;
const offline = context.get('offline') || {};
const msgs = [];
const fehlt = [];

for (const [signal, name, quelleVar, grenzeMin] of SIGNALE) {
    if (quelleVar && (env.get(quelleVar) || (quelleVar === 'BKW_QUELLE' ? 'aus' : 'simulator')) === 'aus') continue;
    const grenze = (grenzeMin || grenzeStd) * 60000;
    const e = abbild[signal];
    const alter = e ? jetzt - e.zeit : jetzt - start;
    if (alter > grenze) {
        fehlt.push(name);
        if (!offline[signal]) {
            offline[signal] = jetzt;
            msgs.push({ log: { stufe: 'fehler', bereich: 'system', melden: 'geraet',
                text: `${name} liefert seit ${Math.round(alter / 60000)} min keine Werte` } });
        }
    } else if (offline[signal]) {
        msgs.push({ log: { stufe: 'info', bereich: 'system', melden: 'geraet',
            text: `${name} wieder online (nach ${Math.round((jetzt - offline[signal]) / 60000)} min)` } });
        delete offline[signal];
    }
}
context.set('offline', offline);
node.status(fehlt.length
    ? { fill: 'red', shape: 'dot', text: 'fehlt: ' + fehlt.join(', ') }
    : { fill: 'green', shape: 'dot', text: 'alle Geräte liefern' });
return msgs.length ? [msgs] : null;

// Tagesbericht (R5): um 7 Uhr für den Vortag
// Ein Knoten für alle drei Schritte, unterschieden nach msg.schritt:
//   (ohne)    → Abfrage 1 bauen: Netz, PV, Wallbox je Minute (Bucket geraete)
//   'geraete' → Antwort merken, Abfrage 2 bauen: Strompreise (Bucket markt)
//   'markt'   → Antwort merken, Abfrage 3 bauen: Netzladen der Strategie (Bucket ems)
//   'ems'     → Bericht rechnen
// ─ Ausgang 1: msg.query → "InfluxDB lesen" (dessen Antwort kommt wieder hierher)
// ─ Ausgang 2: msg.log mit melden 'tagesbericht' → Log
// ─ Umgebung: EINSPEISE_CT (8,0), ABGABEN_CT (nur als Rückfall, wenn kein Endpreis gespeichert ist)
// ─ Kontext: global.meldung_nacht (wird angehängt und geleert)

function mitternachtBerlin(t) {
    // UTC-Zeitpunkt von 0 Uhr deutscher Zeit am Tag von t
    const f = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });
    const p = Object.fromEntries(f.formatToParts(t).map(x => [x.type, x.value]));
    const alsUtc = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second);
    const versatz = alsUtc - Math.floor(t / 1000) * 1000;
    return Date.UTC(+p.year, +p.month - 1, +p.day) - versatz;
}
const fmt = (x, n = 1) => x.toFixed(n).replace('.', ',');

if (!msg.schritt) {
    const stop = mitternachtBerlin(Date.now());
    const start = mitternachtBerlin(stop - 12 * 3600000);
    msg.bericht = { start, stop };
    msg.schritt = 'geraete';
    msg.query = `from(bucket: "geraete")
  |> range(start: ${new Date(start).toISOString()}, stop: ${new Date(stop).toISOString()})
  |> filter(fn: (r) => (r._measurement == "netz" and r._field == "bezug_W") or
                       (r._measurement == "pv" and r._field == "leistung_W") or
                       (r._measurement == "bkw" and r._field == "leistung_W") or
                       (r._measurement == "wallbox" and r._field == "leistung_W"))
  |> aggregateWindow(every: 1m, fn: mean, createEmpty: false)
  |> keep(columns: ["_time", "_value", "_measurement"])`;
    return [msg, null];
}

const b = msg.bericht;
if (msg.schritt === 'geraete') {
    b.geraete = Array.isArray(msg.payload) ? msg.payload : [];
    msg.schritt = 'markt';
    msg.query = `from(bucket: "markt")
  |> range(start: ${new Date(b.start - 3600000).toISOString()}, stop: ${new Date(b.stop).toISOString()})
  |> filter(fn: (r) => r._measurement == "strompreis" and r._field == "preis_ct")
  |> keep(columns: ["_time", "_value"])`;
    return [msg, null];
}
if (msg.schritt === 'markt') {
    b.preise = Array.isArray(msg.payload) ? msg.payload : [];
    msg.schritt = 'ems';
    msg.query = `from(bucket: "ems")
  |> range(start: ${new Date(b.start).toISOString()}, stop: ${new Date(b.stop).toISOString()})
  |> filter(fn: (r) => r._measurement == "ems_strategie" and r._field == "nl_laden")
  |> keep(columns: ["_time", "_value"])`;
    return [msg, null];
}

// Schritt 'ems': rechnen
const nl = Array.isArray(msg.payload) ? msg.payload : [];
const einspeiseCt = parseFloat(env.get('EINSPEISE_CT')) || 8.0;
const preise = b.preise.map(r => [new Date(r._time).getTime(), r._value]).sort((x, y) => x[0] - y[0]);
function preisZu(t) {
    // letzter bekannter Preis vor t (Viertelstunden)
    let p = null;
    for (const [tp, v] of preise) { if (tp <= t) p = v; else break; }
    return p;
}
let bezug = 0, einspeisung = 0, kosten = 0, pv = 0, bkw = 0, auto = 0, ohnePreis = 0;
for (const r of b.geraete) {
    const t = new Date(r._time).getTime() - 60000; // aggregateWindow stempelt das Ende der Minute
    const kWh = r._value / 60000;
    if (r._measurement === 'netz') {
        if (kWh > 0) {
            bezug += kWh;
            const p = preisZu(t);
            if (p === null) ohnePreis += kWh; else kosten += kWh * p / 100;
        } else {
            einspeisung -= kWh;
            kosten += kWh * einspeiseCt / 100;
        }
    } else if (r._measurement === 'pv') pv += Math.max(0, kWh);
    else if (r._measurement === 'bkw') bkw += Math.max(0, kWh);
    else if (r._measurement === 'wallbox') auto += Math.max(0, kWh);
}
const nlStunden = nl.filter(r => r._value >= 1).length * 0.25;
const datum = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit' }).format(b.start);
let text = `📊 Tagesbericht ${datum}.: Strom ${fmt(kosten, 2)} € (Bezug ${fmt(bezug)} kWh, Einspeisung ${fmt(einspeisung)} kWh)` +
    ` · PV ${fmt(pv + bkw)} kWh${bkw > 0.05 ? ` (davon Balkon ${fmt(bkw)})` : ''} · Auto ${fmt(auto)} kWh · Netzladen ${fmt(nlStunden, 2)} h`;
if (ohnePreis > 0.05) text += ` (${fmt(ohnePreis)} kWh ohne Preis)`;
const nacht = global.get('meldung_nacht') || [];
if (nacht.length) text += '\nNachts zurückgehalten:\n' + nacht.map(x => '· ' + x.text).join('\n');
global.set('meldung_nacht', []);
node.status({ fill: 'green', shape: 'dot', text: text.slice(0, 60) });
return [null, { log: { stufe: 'info', bereich: 'system', melden: 'tagesbericht', text,
    daten: { kosten_eur: +kosten.toFixed(2), bezug_kWh: +bezug.toFixed(2), einspeisung_kWh: +einspeisung.toFixed(2),
             pv_kWh: +(pv + bkw).toFixed(2), bkw_kWh: +bkw.toFixed(2), auto_kWh: +auto.toFixed(2), netzladen_h: nlStunden } } }];

// Lastprofil: mittlerer Hausverbrauch ohne Auto je Uhrzeit (deutsche Zeit), letzte 14 Tage
// Zwei Schritte in einem Knoten:
//   msg.schritt fehlt  → Abfrage bauen (Ausgang 1 → "InfluxDB lesen", die Antwort kommt mit msg.schritt = 'antwort' zurück)
//   msg.schritt = 'antwort' → auswerten
// ─ Kontext: global.ems_lastprofil = { werte: [24 × W], tage, zeit }
// Warum Mittelwert und 14 Tage: In Haus-EMS über 60 Tage rückgerechnet. Der Median übersieht die Blöcke der
// Wärmepumpe, der Mittelwert enthält sie (docs/ems.md, „Lastprofil“).
// Ist die InfluxDB nicht erreichbar, bleibt das letzte Profil stehen (R1.6).

if (msg.schritt !== 'antwort') {
    msg.schritt = 'antwort';
    msg.query = `from(bucket: "geraete")
  |> range(start: -14d)
  |> filter(fn: (r) => r._measurement == "haus" and r._field == "ohne_auto_W")
  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)
  |> keep(columns: ["_time", "_value"])`;
    return [msg, null];
}

const zeilen = Array.isArray(msg.payload) ? msg.payload : [];
const stunde = t => parseInt(new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', hour: 'numeric', hourCycle: 'h23' }).format(t), 10);
const summe = new Array(24).fill(0), anzahl = new Array(24).fill(0);
const tage = new Set();
for (const z of zeilen) {
    // aggregateWindow stempelt das Ende der Stunde
    const t = new Date(z._time).getTime() - 3600000;
    const h = stunde(t);
    summe[h] += z._value;
    anzahl[h]++;
    tage.add(new Date(t).toISOString().slice(0, 10));
}
const alt = global.get('ems_lastprofil');
const standard = parseFloat(env.get('LAST_STANDARD_W')) || 500;
const besetzt = anzahl.filter(n => n > 0).length;
if (tage.size < 2 || besetzt < 20) {
    // zu wenig Daten: feste Annahme, bis genug gesammelt ist
    const profil = { werte: new Array(24).fill(standard), tage: tage.size, zeit: Date.now(), quelle: 'Standard' };
    global.set('ems_lastprofil', profil);
    node.status({ fill: 'yellow', shape: 'ring', text: `zu wenig Daten (${tage.size} Tage), fest ${standard} W` });
    return [null, profil];
}
const werte = summe.map((s, h) => Math.round(anzahl[h] ? s / anzahl[h] : (alt ? alt.werte[h] : standard)));
const profil = { werte, tage: tage.size, zeit: Date.now(), quelle: 'InfluxDB' };
global.set('ems_lastprofil', profil);
const tagWh = werte.reduce((a, b) => a + b, 0);
node.status({ fill: 'green', shape: 'dot', text: `${tage.size} Tage · ${(tagWh / 1000).toFixed(1)} kWh/Tag · max ${Math.max(...werte)} W` });
return [null, profil];

// ⚡ EMS-Strategie (alle 15 min): Netzladen (Vorschau), Wasserlinie, Plan für Wallbox und Wärmepumpe
// Übernommen aus Haus-EMS (docs/ems.md), vereinfacht auf eine PV-Batterie.
// ─ Eingang: Inject alle 15 min (und 20 s nach dem Start)
// ─ Ausgang 1: InfluxDB-Punkt (Bucket ems, Messreihe "ems_strategie")
// ─ Ausgang 2: msg.log, nur bei geänderter Entscheidung
// ─ Liest: global.abbild (batterie.soc_pct, netz.bezug_W, wallbox.leistung_W, markt.preise, prognose.pv),
//          global.ems_lastprofil, global.ems_live
// ─ Schreibt: global.ems_nl (Netzladen), global.ems_wl (Wasserlinie), global.ems_plan (Preise für Wallbox und
//            Wärmepumpe), global.ems_haus (teuer: Strom jetzt teurer als bis zur nächsten Sonne)
// ─ Umgebung: BATTERIE_KAPAZITAET_WH, BATTERIE_MAX_W, BATTERIE_MIN_SOC, LAST_STANDARD_W,
//             NL_MODUS, NL_WIRKUNGSGRAD, NL_AUFSCHLAG_CT, NL_LAST_FAKTOR, NL_PV_FAKTOR, NL_MIN_KWH, NL_SOC_MAX, NL_LEISTUNG_W,
//             WL_MODUS, WL_RESERVE, WL_LETZTE_H, WL_PV_FAKTOR

const jetzt = Date.now();
const abbild = global.get('abbild') || {};
function wert(s, maxS) { const e = abbild[s]; return e && jetzt - e.zeit <= maxS * 1000 ? e.wert : null; }
function zahl(n, std) { const v = parseFloat(env.get(n)); return isNaN(v) ? std : v; }
function text(n, std) { const v = env.get(n); return v === undefined || v === null || v === '' ? std : String(v); }
const stunde = t => parseInt(new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', hour: 'numeric', hourCycle: 'h23' }).format(t), 10);
const kWh = wh => (wh / 1000).toFixed(1).replace('.', ',');
const ct = x => x.toFixed(1).replace('.', ',');

const cap = zahl('BATTERIE_KAPAZITAET_WH', 10000);
const maxW = zahl('BATTERIE_MAX_W', 5000);
const socMin = zahl('BATTERIE_MIN_SOC', 10);
const soc = wert('batterie.soc_pct', 300);
const netz = wert('netz.bezug_W', 600);
const wb = wert('wallbox.leistung_W', 600) || 0;
const live = global.get('ems_live');
const liveFrisch = live && jetzt - live.zeit < 120000;

// Preise ab der laufenden Stunde (Endpreis inkl. Abgaben), höchstens 3 h alt
const h0 = Math.floor(jetzt / 3600000) * 3600000;
const preisE = abbild['markt.preise'];
const preise = (preisE && jetzt - preisE.zeit < 3 * 3600000 ? preisE.wert : []).filter(p => p.t >= h0);
const preisJetzt = preise.length && preise[0].t === h0 ? preise[0].ct : null;
const mittel = preise.length ? preise.reduce((a, p) => a + p.ct, 0) / preise.length : null;
const preisZu = t => { const p = preise.find(x => x.t === t); return p ? p.ct : mittel; };

// PV-Prognose (W je Stunde) und Lastprofil (W je Uhrzeit, ohne Auto)
const progE = abbild['prognose.pv'];
const prog = {};
if (progE && jetzt - progE.zeit < 6 * 3600000) for (const x of progE.wert) prog[x.t] = x.W;
const hatPrognose = Object.keys(prog).length > 0;
const pvH = t => prog[t] || 0;
const profil = global.get('ems_lastprofil');
const lastStd = zahl('LAST_STANDARD_W', 500);
const last = t => (profil ? profil.werte[stunde(t)] : lastStd);
const uhr = t => stunde(t) + ' Uhr';
const ueberschussJetzt = liveFrisch ? live.ueberschuss_W : (netz !== null ? Math.max(0, -netz) : 0);

// ───────────── 1. Netzladen: Vorschau ─────────────
// „Fehlt dem Akku Energie, bevor der Strom wieder billiger wird?“ (Haus-EMS seit 9.11.2026)
const NL = {
    modus: text('NL_MODUS', 'vorschau'), eta: zahl('NL_WIRKUNGSGRAD', 0.85), auf: zahl('NL_AUFSCHLAG_CT', 4),
    lastF: zahl('NL_LAST_FAKTOR', 1.2), pvF: zahl('NL_PV_FAKTOR', 0.9), minWh: zahl('NL_MIN_KWH', 1) * 1000,
    socMax: zahl('NL_SOC_MAX', 95), leistung: zahl('NL_LEISTUNG_W', Math.min(maxW, 3000)),
};
let nlLaden = false, nlBedarf = 0, nlGrund;
if (NL.modus === 'aus') nlGrund = 'Netzladen aus';
else if (soc === null) nlGrund = 'Ladestand unbekannt';
else if (preisJetzt === null) nlGrund = 'keine Preise';
else if (ueberschussJetzt >= 150) nlGrund = `PV-Überschuss ${Math.round(ueberschussJetzt)} W`;
else {
    const etaL = Math.sqrt(NL.eta), etaE = Math.sqrt(NL.eta); // je Richtung
    const voll = (100 - socMin) / 100 * cap;
    let inhalt = Math.max(0, (soc - socMin) / 100 * cap);
    // Grenze: eine Stunde lohnt nur, wenn sie nach Verlusten plus Aufschlag (Abstand, Verschleiß) teurer ist
    const grenze = preisJetzt / NL.eta + NL.auf;
    let erste = null, ende = 'nichts fehlt in 24 h', maxNichtLohnend = null;
    for (let i = 0; i < 24; i++) {
