        const preis = preisZu(t);
        if (i > 0 && preis < preisJetzt - 0.5) { ende = `billiger in ${i} h (${ct(preis)} ct)`; break; }
        const netto = (pvH(t) * NL.pvF - last(t) * NL.lastF) * anteil;
