        const hausDecken = haModus === 'aktiv' && (pvLaden || (haus && haus.teuer)) && hausOhneAuto !== null;
        if (hausDecken) {
            befehl = { modus: 'begrenzt', max_laden_W: null, max_entladen_W: rund100(hausOhneAuto - pv - 150) };
