// 🚗 Ladeplanung (jede Minute): Wallbox frei, Pause oder PV-Laden mit Strom in Ampere
// Übernommen aus Haus-EMS (docs/wallbox.md): bis 25 % sofort, 50 % sicher zur Abfahrt, bis 80 % nur in
// günstigen Stunden, darüber frei (Ladeziel im Auto); dazu PV-Laden mit dem Überschuss nach dem Hausakku.
// ─ Eingang: Inject jede Minute
// ─ Ausgang 1: Befehl an die Wallbox (msg.befehl = { modus: 'frei' | 'pause' | 'strom', ampere? }) → Link „Befehl Wallbox“
// ─ Ausgang 2: InfluxDB-Punkt (Bucket ems, Messreihe "wallbox_plan")
// ─ Ausgang 3: msg.log (Regelwechsel, Laden gestartet/pausiert/beendet, Zusage in Gefahr)
// ─ Liest: global.abbild (auto.soc_pct, wallbox.status, wallbox.leistung_W), global.ems_plan, global.ems_ueberschuss
// ─ Schreibt: global.wallbox_plan = { regel, befehl, zeit } (für die EMS-Ausführung)
// ─ Umgebung: WB_MODUS, WB_STRATEGIE, WB_ABFAHRT, WB_ABFAHRT_TAGE, WB_SOFORT_SOC, WB_PFLICHT_SOC, WB_ZIEL_SOC,
//             WB_AKKU_KWH, WB_WIRKUNGSGRAD, WB_PHASEN, WB_MAX_A, WB_MIN_A, WB_SOC_MAX_ALTER_MIN, WB_TEUER_ANTEIL,
//             WB_PV_MODUS, WB_PV_MIN_KW, WB_PV_HALT_KW, WB_MELDUNGEN

const jetzt = Date.now();
const abbild = global.get('abbild') || {};
function wert(s, maxS) { const e = abbild[s]; return e && jetzt - e.zeit <= maxS * 1000 ? e.wert : null; }
function zahl(n, std) { const v = parseFloat(env.get(n)); return isNaN(v) ? std : v; }
function text(n, std) { const v = env.get(n); return v === undefined || v === null || v === '' ? std : String(v); }
const fmt = (x, n = 1) => x.toFixed(n).replace('.', ',');
const stunde = t => parseInt(new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', hour: 'numeric', hourCycle: 'h23' }).format(t), 10);
const wochentag = t => ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].indexOf(
    new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Berlin', weekday: 'short' }).format(t)) + 1; // 1 = Montag

const modus = text('WB_MODUS', 'beobachten');
const strategie = text('WB_STRATEGIE', 'plan');
const SOFORT = zahl('WB_SOFORT_SOC', 25), PFLICHT = zahl('WB_PFLICHT_SOC', 50), ZIEL = zahl('WB_ZIEL_SOC', 80);
const akkuKWh = zahl('WB_AKKU_KWH', 60), eta = zahl('WB_WIRKUNGSGRAD', 0.9);
const phasen = zahl('WB_PHASEN', 3), maxA = zahl('WB_MAX_A', 16), minA = zahl('WB_MIN_A', 6);
const wJeA = phasen * 230;
const ladeKW = maxA * wJeA / 1000;
const teuerAnteil = zahl('WB_TEUER_ANTEIL', 0.5);
const abfahrtH = parseInt(text('WB_ABFAHRT', '06:00').split(':')[0], 10);
const abfahrtTage = text('WB_ABFAHRT_TAGE', '1,2,3,4,5').split(',').map(s => parseInt(s, 10));

const soc = wert('auto.soc_pct', zahl('WB_SOC_MAX_ALTER_MIN', 90) * 60);
const status = wert('wallbox.status', 300);
const leistung = wert('wallbox.leistung_W', 300);
const angesteckt = ['angesteckt', 'laedt', 'pausiert'].includes(status);

// Preise ab der laufenden Stunde (Plan des EMS, höchstens 20 min alt)
const h0 = Math.floor(jetzt / 3600000) * 3600000;
const plan = global.get('ems_plan');
const preise = plan && jetzt - plan.zeit < 20 * 60000 ? (plan.preise || []).filter(p => p.t >= h0) : [];

// nächste Abfahrt: erste volle Stunde WB_ABFAHRT an einem Abfahrtstag
let abfahrt = null;
for (let i = 1; i <= 8 * 24; i++) {
    const t = h0 + i * 3600000;
    if (stunde(t) === abfahrtH && abfahrtTage.includes(wochentag(t))) { abfahrt = t; break; }
}
const stundenFuer = pp => Math.ceil(Math.max(0, pp) / 100 * akkuKWh / eta / ladeKW);
const uhr = t => stunde(t) + ' Uhr';

// Stunden bis zur Abfahrt mit Preis (unbekannte Stunden mit dem Mittel der bekannten)
const mittelPreis = preise.length ? preise.reduce((a, p) => a + p.ct, 0) / preise.length : null;
const bisAbfahrt = [];
if (abfahrt) for (let t = h0; t < abfahrt; t += 3600000) {
    const p = preise.find(x => x.t === t);
    bisAbfahrt.push({ t, ct: p ? p.ct : mittelPreis, bekannt: !!p });
}
const teuerste = (liste, anteil) => {
    const n = Math.floor(liste.length * anteil);
    return new Set(liste.slice().sort((a, b) => b.ct - a.ct).slice(0, n).map(x => x.t));
};
const billigsteN = (liste, n) => new Set(liste.slice().sort((a, b) => a.ct - b.ct || a.t - b.t).slice(0, n).map(x => x.t));

let regel, frei, grund, bedarfKWh = 0, noetig = 0;
if (!preise.length) {
    regel = 'ohne_preise'; frei = true; grund = 'keine Preise: frei (lieber laden als stehen bleiben)';
} else if (soc === null || strategie === 'sperre') {
    // Regel „teuerste Stunden“: Ladestand unbekannt oder so eingestellt
    const teuer = teuerste(preise, teuerAnteil).has(h0);
    regel = 'sperre'; frei = !teuer;
    grund = (soc === null ? 'Ladestand unbekannt, ' : '') + (teuer ? 'teure Stunde: Pause' : 'keine teure Stunde: frei');
} else if (soc < SOFORT) {
    regel = 'sofort'; frei = true; grund = `bis ${SOFORT} %: sofort`;
} else if (soc >= ZIEL) {
    regel = 'frei'; frei = true; grund = `ab ${ZIEL} %: Ladeziel im Auto entscheidet`;
} else {
    bedarfKWh = (ZIEL - soc) / 100 * akkuKWh / eta;
    const nZiel = stundenFuer(ZIEL - soc);
    const guenstig = bisAbfahrt.filter(x => !teuerste(bisAbfahrt, teuerAnteil).has(x.t));
    const zielStunden = billigsteN(guenstig, nZiel);
    if (soc < PFLICHT) {
        noetig = stundenFuer(PFLICHT - soc);
        if (bisAbfahrt.length <= noetig) { regel = 'pflicht'; frei = true; grund = `bis ${PFLICHT} %: Zeit reicht knapp, sofort`; }
        else if (billigsteN(bisAbfahrt, noetig).has(h0)) { regel = 'pflicht'; frei = true; grund = `bis ${PFLICHT} % zur Abfahrt: günstige Stunde (${noetig} h nötig)`; }
        else if (zielStunden.has(h0)) { regel = 'ziel'; frei = true; grund = `bis ${ZIEL} %: günstige Stunde (${nZiel} h)`; }
        else { regel = 'pflicht'; frei = false; grund = `warten auf günstige Stunde (${noetig} h bis ${PFLICHT} %, Abfahrt ${uhr(abfahrt)})`; }
    } else {
        noetig = nZiel;
        if (zielStunden.has(h0)) { regel = 'ziel'; frei = true; grund = `bis ${ZIEL} %: günstige Stunde (${nZiel} h)`; }
        else { regel = 'ziel'; frei = false; grund = `warten auf günstige Stunde (${nZiel} h bis ${ZIEL} %)`; }
    }
}

// PV-Laden: würde das Auto gerade nicht laden, steckt aber und ist unter dem Ziel → mit dem Überschuss laden
const pvModus = text('WB_PV_MODUS', 'aktiv');
const ue = global.get('ems_ueberschuss');
const ueW = ue && jetzt - ue.zeit < 120000 ? ue.car_W : 0;
const pv = context.get('pv') || { aktiv: false, ueber: 0, unter: 0, ampere: 0, geaendert: 0 };
const pvMoeglich = !frei && angesteckt && (soc === null || soc < ZIEL) && pvModus !== 'aus';
if (pvMoeglich) {
    pv.ueber = ueW >= zahl('WB_PV_MIN_KW', 4.2) * 1000 ? pv.ueber + 1 : 0;
    pv.unter = ueW < zahl('WB_PV_HALT_KW', 3.6) * 1000 ? pv.unter + 1 : 0;
    if (!pv.aktiv && pv.ueber >= 2) { pv.aktiv = true; pv.geaendert = 0; }
    if (pv.aktiv && pv.unter >= 2) pv.aktiv = false;
} else { pv.aktiv = false; pv.ueber = 0; pv.unter = 0; }
let befehl;
if (pv.aktiv) {
    // Ampere dem Überschuss nachführen, höchstens alle 2 min (schont Wallbox und Auto).
    // ems_ueberschuss enthält beim PV-Laden die Ladeleistung des Autos schon (EMS-Ausführung).
    const ziel = Math.min(maxA, Math.max(minA, Math.floor(ueW / wJeA)));
    if (!pv.ampere || jetzt - pv.geaendert >= 120000) { if (ziel !== pv.ampere) pv.geaendert = jetzt; pv.ampere = ziel; }
    befehl = { modus: 'strom', ampere: pv.ampere };
    regel = 'pv'; grund = `PV-Überschuss ${fmt(ueW / 1000)} kW (${pv.ampere} A)`;
} else {
    pv.ampere = 0;
    befehl = frei ? { modus: 'frei' } : { modus: 'pause' };
}
context.set('pv', pv);
const effektivModus = pvModus === 'aktiv' ? befehl : (frei ? { modus: 'frei' } : { modus: 'pause' });
global.set('wallbox_plan', { regel: effektivModus.modus === 'strom' ? 'pv' : regel, befehl: effektivModus, grund, zeit: jetzt });

// Senden: bei Änderung und alle 15 min, nur im Modus aktiv
const st = context.get('st') || {};
const geaendert = JSON.stringify(st.befehl) !== JSON.stringify(effektivModus);
const senden = modus === 'aktiv' && (geaendert || jetzt - (st.gesendet || 0) >= 15 * 60000);
if (senden) st.gesendet = jetzt;

// Meldungen: Laden gestartet (3 min > 1 kW), pausiert (Sperre greift, Auto steckt), beendet (3 min nichts, mit kWh)
const logs = [];
const melden = text('WB_MELDUNGEN', 'an') === 'an' && modus === 'aktiv' ? 'wallbox' : undefined;
const lv = st.lv || { laedt: false, ueber: 0, unter: 0, energie_Wh: 0, start: 0 };
const fliesst = (leistung || 0) > 1000;
if (lv.laedt || fliesst) lv.energie_Wh += Math.max(0, leistung || 0) / 60;
lv.ueber = fliesst ? lv.ueber + 1 : 0;
lv.unter = fliesst ? 0 : lv.unter + 1;
const socText = (soc !== null ? ` · Auto ${Math.round(soc)} %` : '') + (modus !== 'aktiv' ? ` (WB_MODUS=${modus}, Plan nicht gesendet)` : '');
if (!lv.laedt && lv.ueber >= 3) {
    lv.laedt = true; lv.start = lv.start || jetzt - 3 * 60000;
    logs.push({ log: { stufe: 'info', bereich: 'wallbox', melden, text: `🔌 Wallbox: Laden gestartet – Regel: ${grund}${socText}` } });
} else if (lv.laedt && lv.unter >= 3) {
    lv.laedt = false;
    if (!(befehl.modus === 'pause' && angesteckt)) {
        const dauer = Math.round((jetzt - lv.start) / 60000);
        logs.push({ log: { stufe: 'info', bereich: 'wallbox', melden,
            text: `✅ Wallbox: Laden beendet – ${angesteckt ? 'vom Auto' : 'abgesteckt'}${socText} · geladen ${fmt(lv.energie_Wh / 1000)} kWh in ${Math.floor(dauer / 60)} h ${dauer % 60} min` } });
        lv.energie_Wh = 0; lv.start = 0;
    }
}
if (!angesteckt && !lv.laedt) { lv.energie_Wh = 0; lv.start = 0; }
if (geaendert && st.befehl && effektivModus.modus === 'pause' && angesteckt) {
    logs.push({ log: { stufe: 'info', bereich: 'wallbox', melden, text: `⏸ Wallbox: Laden pausiert – Regel: ${grund}${socText}` } });
}
st.lv = lv;

// Zusage in Gefahr: Auto steckt, unter der Pflicht, Wallbox frei, aber 10 min fließt nachweislich kein Strom
const gefahr = modus === 'aktiv' && angesteckt && soc !== null && soc < PFLICHT && befehl.modus !== 'pause' && leistung !== null && leistung <= 1000;
st.gefahrMin = gefahr ? (st.gefahrMin || 0) + 1 : 0;
if (st.gefahrMin === 10) {
    logs.push({ log: { stufe: 'warnung', bereich: 'wallbox', melden: 'zusage',
        text: `Zusage in Gefahr: Auto bei ${Math.round(soc)} % (Pflicht ${PFLICHT} %), Wallbox frei, aber seit 10 min kein Strom` } });
    st.gefahr = true;
} else if (st.gefahr && !gefahr) {
    logs.push({ log: { stufe: 'info', bereich: 'wallbox', melden: 'zusage', text: 'Entwarnung: Auto lädt wieder oder Pflicht erreicht' } });
    st.gefahr = false;
}
if (st.regel !== regel && st.regel !== undefined && !logs.length) {
    logs.push({ log: { stufe: 'info', bereich: 'wallbox', text: `Ladeplanung: ${grund}` } });
}
st.befehl = effektivModus; st.regel = regel;
context.set('st', st);

const fields = { regel, befehl: effektivModus.modus, frei: frei ? 1 : 0, grund, ampere: effektivModus.ampere || 0,
    pv_moeglich: pvMoeglich ? 1 : 0, pv_ueberschuss_W: Math.round(ueW), angesteckt: angesteckt ? 1 : 0,
    bedarf_kWh: +bedarfKWh.toFixed(1), stunden_noetig: noetig, bekannte_stunden: preise.length, gesendet: senden ? 1 : 0 };
if (soc !== null) fields.soc = soc;
if (leistung !== null) fields.leistung_W = leistung;
if (abfahrt) fields.bis_abfahrt_h = +((abfahrt - jetzt) / 3600000).toFixed(1);
if (preise.length) fields.preis_ct = preise[0].ct;

node.status({ fill: effektivModus.modus === 'pause' ? 'yellow' : 'green', shape: senden ? 'dot' : 'ring',
    text: `${effektivModus.modus}${effektivModus.ampere ? ' ' + effektivModus.ampere + ' A' : ''} – ${grund}` + (modus !== 'aktiv' ? ` · ${modus}` : '') });
return [senden ? { befehl: Object.assign({ grund, zeit: jetzt }, effektivModus) } : null,
        { payload: [{ measurement: 'wallbox_plan', tags: { quelle: 'ems' }, fields, timestamp: new Date(jetzt) }] },
        logs.length ? logs : null];

const GERAET = 'wallbox';
// Befehl verteilen (je Gerät, GERAET steht in der ersten Zeile, vom Generator eingesetzt)
// ─ Eingang: msg.befehl vom EMS (Batterie), von der Ladeplanung (Wallbox) oder der Wärmepumpen-Steuerung
// ─ Ausgang 1: an den Geräte-Adapter (nur wenn <GERÄT>_QUELLE = geraet)
// ─ Kontext: global.befehl_<geraet> = letzter Befehl (der Simulator liest ihn von dort)
//            global.abbild['befehl.<geraet>'] (zur Anzeige)
// ─ Umgebung: <GERÄT>_QUELLE: simulator (Standard) | geraet | aus

const QUELLE_VAR = { batterie: 'BATTERIE_QUELLE', wallbox: 'WALLBOX_QUELLE', wp: 'WP_QUELLE' }[GERAET];
const quelle = env.get(QUELLE_VAR) || 'simulator';
const b = msg.befehl;
if (!b) return null;
global.set('befehl_' + GERAET, b);
const abbild = global.get('abbild') || {};
abbild['befehl.' + GERAET] = { wert: b, einheit: '', zeit: Date.now(), quelle: 'ems' };
global.set('abbild', abbild);

const kurz = Object.entries(b).filter(([k]) => !['grund', 'zeit'].includes(k)).map(([k, v]) => `${k}=${v}`).join(' ');
node.status({ fill: quelle === 'aus' ? 'grey' : 'green', shape: 'dot', text: `${quelle}: ${kurz}` });
return quelle === 'geraet' ? msg : null;

const GERAET = 'wallbox';
// VORLAGE – Adapter: Befehl ans Gerät senden (GERAET steht in der ersten Zeile)
// Hier wird beim Hackathon das echte Gerät angebunden. Siehe docs/geraete-adapter.md.
//
// Eingang msg.befehl (nur, wenn <GERÄT>_QUELLE = geraet):
//   batterie: { modus: 'eigenverbrauch' }
//             { modus: 'laden', leistung_W }                        aus dem Netz laden
//             { modus: 'begrenzt', max_laden_W, max_entladen_W }    null = keine Grenze, 0 = gesperrt
//   wallbox:  { modus: 'frei' } | { modus: 'pause' } | { modus: 'strom', ampere }
//   wp:       { sgready: 2|3, anhebung_K, ww_absenken }
// Ausgang → HTTP-/Modbus-/MQTT-Knoten des Geräts.
// Sicherheit: Gerät so einstellen, dass es ohne neuen Befehl nach einigen Minuten in den Normalbetrieb fällt
// (Timeout), sonst bleibt bei einem Ausfall von Node-RED der letzte Befehl stehen.

const b = msg.befehl;

// ▼▼▼ Hier den Befehl in Register/Anfrage des Geräts übersetzen ▼▼▼
const anfrage = null; // z. B. { payload: { value: b.max_laden_W, fc: 6, unitid: 1, address: 1234, quantity: 1 } }
// ▲▲▲

if (!anfrage) {
    if (!context.get('gewarnt')) {
        context.set('gewarnt', true);
        node.warn(`Befehl für ${GERAET} kann nicht gesendet werden: Adapter noch nicht umgesetzt`);
    }
    node.status({ fill: 'yellow', shape: 'ring', text: 'Adapter noch nicht umgesetzt' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: JSON.stringify(b).slice(0, 60) });
return anfrage;

const GERAET = 'wallbox';
// VORLAGE – Adapter: Messwerte lesen (GERAET steht in der ersten Zeile)
// Hier wird beim Hackathon das echte Gerät angebunden. Siehe docs/geraete-adapter.md.
//
// Aufgabe: das Gerät abfragen (vorgeschaltet: HTTP-, Modbus- oder MQTT-Knoten) und die Werte in das
// einheitliche Format bringen. Ausgang → Link „→ Messwerte“:
//   msg.geraet = GERAET
//   msg.quelle = 'geraet'
//   msg.payload = { … } mit genau diesen Feldern (fehlende weglassen):
//     pv:       { leistung_W }                                   (≥ 0)
//     bkw:      { leistung_W, soc_pct? }                         Balkonkraftwerk: AC-Abgabe ≥ 0, Akku-SoC falls vorhanden
//     netz:     { bezug_W }                                      (> 0 Bezug, < 0 Einspeisung)
//     batterie: { soc_pct, leistung_W }                          (leistung_W > 0 Entladen, < 0 Laden)
//     wallbox:  { leistung_W, status, ampere }                   status: getrennt | angesteckt | laedt | pausiert | stoerung
//     auto:     { soc_pct }                                      (Ladestand des Autos, falls abrufbar)
//     wp:       { leistung_W, status, aussen_C?, raum_C? }       status: aus | heizen | warmwasser | stoerung
//
// Solange <GERÄT>_QUELLE nicht "geraet" ist, tut dieser Knoten nichts.

const QUELLE_VAR = { pv: 'PV_QUELLE', bkw: 'BKW_QUELLE', netz: 'NETZ_QUELLE', batterie: 'BATTERIE_QUELLE', wallbox: 'WALLBOX_QUELLE',
    auto: 'AUTO_QUELLE', wp: 'WP_QUELLE' }[GERAET];
if ((env.get(QUELLE_VAR) || 'simulator') !== 'geraet') {
    node.status({ fill: 'grey', shape: 'ring', text: 'nicht aktiv (' + QUELLE_VAR + ' ≠ geraet)' });
    return null;
}

// ▼▼▼ Hier die Antwort des Geräts (msg.payload) umrechnen ▼▼▼
const roh = msg.payload;
const werte = null; // z. B. { leistung_W: roh.P_PV }
// ▲▲▲

if (!werte) {
    if (!context.get('gewarnt')) {
        context.set('gewarnt', true);
        node.warn(`${QUELLE_VAR}=geraet, aber der Adapter für ${GERAET} ist noch nicht umgesetzt`);
    }
    node.status({ fill: 'yellow', shape: 'ring', text: 'Adapter noch nicht umgesetzt' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: JSON.stringify(werte).slice(0, 60) });
return { geraet: GERAET, quelle: 'geraet', payload: werte };

const GERAET = 'auto';
// VORLAGE – Adapter: Messwerte lesen (GERAET steht in der ersten Zeile)
// Hier wird beim Hackathon das echte Gerät angebunden. Siehe docs/geraete-adapter.md.
//
// Aufgabe: das Gerät abfragen (vorgeschaltet: HTTP-, Modbus- oder MQTT-Knoten) und die Werte in das
// einheitliche Format bringen. Ausgang → Link „→ Messwerte“:
//   msg.geraet = GERAET
//   msg.quelle = 'geraet'
//   msg.payload = { … } mit genau diesen Feldern (fehlende weglassen):
//     pv:       { leistung_W }                                   (≥ 0)
//     bkw:      { leistung_W, soc_pct? }                         Balkonkraftwerk: AC-Abgabe ≥ 0, Akku-SoC falls vorhanden
//     netz:     { bezug_W }                                      (> 0 Bezug, < 0 Einspeisung)
//     batterie: { soc_pct, leistung_W }                          (leistung_W > 0 Entladen, < 0 Laden)
//     wallbox:  { leistung_W, status, ampere }                   status: getrennt | angesteckt | laedt | pausiert | stoerung
//     auto:     { soc_pct }                                      (Ladestand des Autos, falls abrufbar)
//     wp:       { leistung_W, status, aussen_C?, raum_C? }       status: aus | heizen | warmwasser | stoerung
//
// Solange <GERÄT>_QUELLE nicht "geraet" ist, tut dieser Knoten nichts.

const QUELLE_VAR = { pv: 'PV_QUELLE', bkw: 'BKW_QUELLE', netz: 'NETZ_QUELLE', batterie: 'BATTERIE_QUELLE', wallbox: 'WALLBOX_QUELLE',
    auto: 'AUTO_QUELLE', wp: 'WP_QUELLE' }[GERAET];
if ((env.get(QUELLE_VAR) || 'simulator') !== 'geraet') {
    node.status({ fill: 'grey', shape: 'ring', text: 'nicht aktiv (' + QUELLE_VAR + ' ≠ geraet)' });
    return null;
}

// ▼▼▼ Hier die Antwort des Geräts (msg.payload) umrechnen ▼▼▼
const roh = msg.payload;
const werte = null; // z. B. { leistung_W: roh.P_PV }
// ▲▲▲

if (!werte) {
    if (!context.get('gewarnt')) {
        context.set('gewarnt', true);
        node.warn(`${QUELLE_VAR}=geraet, aber der Adapter für ${GERAET} ist noch nicht umgesetzt`);
    }
    node.status({ fill: 'yellow', shape: 'ring', text: 'Adapter noch nicht umgesetzt' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: JSON.stringify(werte).slice(0, 60) });
return { geraet: GERAET, quelle: 'geraet', payload: werte };

// Ladestand des Autos von Hand setzen: GET/POST http://<pi>:1880/radler/auto?soc=55
// Für Autos ohne abrufbaren Ladestand (AUTO_QUELLE = manuell). Gilt WB_SOC_MAX_ALTER_MIN lang, danach plant die
// Ladeplanung nach „teuerste Stunden“.
// ─ Ausgang 1: Messwert → Link „→ Messwerte“
// ─ Ausgang 2: HTTP-Antwort

const q = Object.assign({}, msg.req && msg.req.query, typeof msg.payload === 'object' ? msg.payload : {});
const soc = parseFloat(q.soc);
if (isNaN(soc) || soc < 0 || soc > 100) {
    return [null, { statusCode: 400, payload: { fehler: 'soc fehlt oder ungültig (0–100)' }, res: msg.res }];
}
node.status({ fill: 'green', shape: 'dot', text: `Auto ${soc} % (von Hand)` });
return [{ geraet: 'auto', quelle: 'manuell', payload: { soc_pct: soc } },
        { statusCode: 200, payload: { ok: true, soc_pct: soc }, res: msg.res }];

// 🌡️ Wärmepumpe steuern (jede Minute): Anhebung bei PV-Überschuss und günstigem Strom, nie mitten im Heizlauf
// Übernommen aus Haus-EMS (docs/waermepumpe.md), geräteunabhängig: der Befehl enthält SG-Ready-Zustand UND
// Sollwertanhebung; der Adapter nimmt, was seine Wärmepumpe kann.
// ─ Eingang: Inject jede Minute
// ─ Ausgang 1: Befehl (msg.befehl = { sgready: 2|3, anhebung_K, ww_absenken, grund }) → Link „Befehl Wärmepumpe“
// ─ Ausgang 2: InfluxDB-Punkt (Bucket ems, Messreihe "wp_steuerung")
// ─ Ausgang 3: msg.log bei geänderter Anhebung
// ─ Liest: global.abbild (wp.status, wp.leistung_W, wp.aussen_C oder wetter.temperatur_C, wp.raum_C),
//          global.ems_live, global.ems_plan
// ─ Umgebung: WP_MODUS, WP_HEIZGRENZE_C, ANHEBUNG_PV_K, ANHEBUNG_GUENSTIG_K, WP_GUENSTIG_ANTEIL, PV_START_W, PV_HALTEN_W,
//             PV_AUS_MIN, PV_AKKU_SOC, WP_PV_PROGNOSE_WH, RAUM_MAX_C, NACHHEIZ_K, NACHHEIZ_MIN, WW_NACHT_VON, WW_NACHT_BIS
//
// SG-Ready: 1 = Sperre (nicht genutzt), 2 = Normalbetrieb, 3 = Einschaltempfehlung (mehr heizen), 4 = Anlaufbefehl (nicht genutzt)

const jetzt = Date.now();
const abbild = global.get('abbild') || {};
function wert(s, maxS) { const e = abbild[s]; return e && jetzt - e.zeit <= maxS * 1000 ? e.wert : null; }
function zahl(n, std) { const v = parseFloat(env.get(n)); return isNaN(v) ? std : v; }
function text(n, std) { const v = env.get(n); return v === undefined || v === null || v === '' ? std : String(v); }
const stunde = t => parseInt(new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', hour: 'numeric', hourCycle: 'h23' }).format(t), 10);

const modus = text('WP_MODUS', 'beobachten');
const st = context.get('st') || { anhebung: 0, pvFenster: false, pvSeit: 0, pvUnterSeit: 0, zuWarm: false, geaendert: 0,
    lief: false, wwVorher: false, nachheizBis: 0 };

// Außentemperatur, Mittel 24 h (Proben alle 10 min)
const aussen = wert('wp.aussen_C', 900) ?? wert('wetter.temperatur_C', 1800);
const proben = (context.get('aussen') || []).filter(x => jetzt - x[0] <= 86400000);
if (aussen !== null && (!proben.length || jetzt - proben[proben.length - 1][0] >= 600000)) proben.push([jetzt, aussen]);
context.set('aussen', proben);
const aussen24 = proben.length ? proben.reduce((a, x) => a + x[1], 0) / proben.length : null;
const heizzeit = aussen24 === null ? true : aussen24 < zahl('WP_HEIZGRENZE_C', 15);

// Räume zu warm? (optional; ohne Raumwert gilt „nicht zu warm“)
const raum = wert('wp.raum_C', 3600);
const raumMax = zahl('RAUM_MAX_C', 22);
if (raum !== null) st.zuWarm = st.zuWarm ? raum > raumMax - 0.3 : raum >= raumMax;
else st.zuWarm = false;

const status = wert('wp.status', 300);               // 'aus' | 'heizen' | 'warmwasser' | 'stoerung'
const heizt = status === 'heizen';
const wpW = wert('wp.leistung_W', 300) || 0;

// Überschuss: Einspeisung minus Akku-Entladung plus Strom der Wärmepumpe (Mittel 5 min);
// ab PV_AKKU_SOC zählt auch die Ladung des Akkus (er ist fast voll)
const live = global.get('ems_live');
let ue = null;
if (live && jetzt - live.zeit < 120000) {
    const wpMittel = (context.get('wpw') || []).filter(x => jetzt - x[0] <= 300000);
    wpMittel.push([jetzt, wpW]); context.set('wpw', wpMittel);
    ue = live.frei_W + wpMittel.reduce((a, x) => a + x[1], 0) / wpMittel.length;
    if (live.soc !== null && live.soc >= zahl('PV_AKKU_SOC', 80)) ue += live.laden_W || 0;
}

// PV-Fenster: öffnet ab PV_START_W, endet erst, wenn der Überschuss PV_AUS_MIN unter PV_HALTEN_W liegt,
// frühestens nach 30 min und nie in einem Heizlauf
if (ue !== null && ue >= zahl('PV_START_W', 1500) && !st.pvFenster) { st.pvFenster = true; st.pvSeit = jetzt; st.pvUnterSeit = 0; }
if (st.pvFenster) {
    if (ue === null || ue < zahl('PV_HALTEN_W', 1000)) st.pvUnterSeit = st.pvUnterSeit || jetzt; else st.pvUnterSeit = 0;
    if (st.pvUnterSeit && jetzt - st.pvUnterSeit >= zahl('PV_AUS_MIN', 20) * 60000 && jetzt - st.pvSeit >= 30 * 60000 && !heizt) {
        st.pvFenster = false;
    }
}

// Günstiges Fenster: die laufende Stunde gehört zu den billigsten WP_GUENSTIG_ANTEIL der bekannten Preise
// und die Sonne bringt in 12 h wenig
const plan = global.get('ems_plan');
let guenstig = false;
if (plan && jetzt - plan.zeit < 20 * 60000 && plan.preise && plan.preise.length) {
    const h0 = Math.floor(jetzt / 3600000) * 3600000;
    const liste = plan.preise.filter(p => p.t >= h0);
    const n = Math.max(1, Math.floor(liste.length * zahl('WP_GUENSTIG_ANTEIL', 0.25)));
    const billig = new Set(liste.slice().sort((a, b) => a.ct - b.ct).slice(0, n).map(p => p.t));
    guenstig = billig.has(h0) && plan.pv12h_Wh < zahl('WP_PV_PROGNOSE_WH', 15000);
}

// Warmwasser eben fertig → kurz anheben, damit der Heizlauf direkt anschließt (spart Kompressorstarts)
const ww = status === 'warmwasser';
if (st.wwVorher && !ww) st.nachheizBis = jetzt + zahl('NACHHEIZ_MIN', 3) * 60000;
st.wwVorher = ww;

let ziel = 0, grund;
if (!heizzeit) grund = `keine Heizzeit (außen Ø ${aussen24.toFixed(1)} °C)`;
else if (st.zuWarm) grund = `Räume zu warm (${raum} °C)`;
else if (st.pvFenster) { ziel = zahl('ANHEBUNG_PV_K', 2); grund = `PV-Überschuss ${Math.round(ue || 0)} W`; }
else if (guenstig) { ziel = zahl('ANHEBUNG_GUENSTIG_K', 2); grund = 'günstiger Strom'; }
else grund = 'normal';
if (jetzt < st.nachheizBis && ziel < zahl('NACHHEIZ_K', 0.5) && heizzeit) { ziel = zahl('NACHHEIZ_K', 0.5); grund = 'Heizlauf an Warmwasser anhängen'; }

// Anhebung endet erst nach dem Heizlauf; sonst ändert sie sich höchstens alle 2 min (Nachheizen sofort)
let anhebung = st.anhebung;
if (modus === 'aus') { anhebung = 0; grund = 'Steuerung aus'; }
else if (ziel < st.anhebung && heizt) grund += ', bis Ende Heizlauf';
else if (ziel !== st.anhebung && (jetzt - st.geaendert >= 120000 || grund.startsWith('Heizlauf an'))) { anhebung = ziel; }
const geaendert = anhebung !== st.anhebung;
if (geaendert) st.geaendert = jetzt;

// Warmwasser absenken (falls die Wärmepumpe einen Sollwert annimmt): nachts und während einer Anhebung ab 1 K,
// damit die Wärme in den Estrich geht und das Warmwasser keinen Heizlauf unterbricht
const h = stunde(jetzt);
const nachtVon = zahl('WW_NACHT_VON', 1), nachtBis = zahl('WW_NACHT_BIS', 5);
const wwAbsenken = modus !== 'aus' && ((h >= nachtVon && h < nachtBis) || anhebung >= 1 || heizt);

const befehl = { sgready: anhebung > 0 ? 3 : 2, anhebung_K: anhebung, ww_absenken: wwAbsenken };
const senden = modus === 'aktiv' && (geaendert || JSON.stringify(befehl) !== JSON.stringify(st.befehl) || jetzt - (st.gesendet || 0) >= 15 * 60000);
if (senden) st.gesendet = jetzt;
const logs = [];
if (geaendert) logs.push({ log: { stufe: 'info', bereich: 'wp',
    text: `Wärmepumpe: Anhebung ${st.anhebung} → ${anhebung} K (SG-Ready ${befehl.sgready}): ${grund}` + (modus !== 'aktiv' ? ` (WP_MODUS=${modus})` : '') } });
st.anhebung = anhebung; st.befehl = befehl;
context.set('st', st);

const fields = { anhebung_K: anhebung, ziel_K: ziel, sgready: befehl.sgready, grund, heizzeit: heizzeit ? 1 : 0,
    pv_fenster: st.pvFenster ? 1 : 0, guenstig: guenstig ? 1 : 0, heizen: heizt ? 1 : 0, ww_absenken: wwAbsenken ? 1 : 0,
    gesendet: senden ? 1 : 0 };
if (ue !== null) fields.ueberschuss_W = Math.round(ue);
if (raum !== null) fields.raum_C = raum;
if (aussen24 !== null) fields.aussen24_C = +aussen24.toFixed(1);

node.status({ fill: anhebung > 0 ? 'blue' : 'green', shape: senden ? 'dot' : 'ring',
    text: `+${anhebung} K (SG ${befehl.sgready}) – ${grund}` + (modus !== 'aktiv' ? ` · ${modus}` : '') });
return [senden ? { befehl: Object.assign({ grund, zeit: jetzt }, befehl) } : null,
        { payload: [{ measurement: 'wp_steuerung', tags: { quelle: 'ems' }, fields, timestamp: new Date(jetzt) }] },
        logs.length ? logs : null];

const GERAET = 'wp';
// Befehl verteilen (je Gerät, GERAET steht in der ersten Zeile, vom Generator eingesetzt)
// ─ Eingang: msg.befehl vom EMS (Batterie), von der Ladeplanung (Wallbox) oder der Wärmepumpen-Steuerung
// ─ Ausgang 1: an den Geräte-Adapter (nur wenn <GERÄT>_QUELLE = geraet)
// ─ Kontext: global.befehl_<geraet> = letzter Befehl (der Simulator liest ihn von dort)
//            global.abbild['befehl.<geraet>'] (zur Anzeige)
// ─ Umgebung: <GERÄT>_QUELLE: simulator (Standard) | geraet | aus

const QUELLE_VAR = { batterie: 'BATTERIE_QUELLE', wallbox: 'WALLBOX_QUELLE', wp: 'WP_QUELLE' }[GERAET];
const quelle = env.get(QUELLE_VAR) || 'simulator';
const b = msg.befehl;
if (!b) return null;
global.set('befehl_' + GERAET, b);
const abbild = global.get('abbild') || {};
abbild['befehl.' + GERAET] = { wert: b, einheit: '', zeit: Date.now(), quelle: 'ems' };
global.set('abbild', abbild);

const kurz = Object.entries(b).filter(([k]) => !['grund', 'zeit'].includes(k)).map(([k, v]) => `${k}=${v}`).join(' ');
node.status({ fill: quelle === 'aus' ? 'grey' : 'green', shape: 'dot', text: `${quelle}: ${kurz}` });
return quelle === 'geraet' ? msg : null;

const GERAET = 'wp';
// VORLAGE – Adapter: Befehl ans Gerät senden (GERAET steht in der ersten Zeile)
// Hier wird beim Hackathon das echte Gerät angebunden. Siehe docs/geraete-adapter.md.
//
// Eingang msg.befehl (nur, wenn <GERÄT>_QUELLE = geraet):
//   batterie: { modus: 'eigenverbrauch' }
//             { modus: 'laden', leistung_W }                        aus dem Netz laden
//             { modus: 'begrenzt', max_laden_W, max_entladen_W }    null = keine Grenze, 0 = gesperrt
//   wallbox:  { modus: 'frei' } | { modus: 'pause' } | { modus: 'strom', ampere }
//   wp:       { sgready: 2|3, anhebung_K, ww_absenken }
// Ausgang → HTTP-/Modbus-/MQTT-Knoten des Geräts.
// Sicherheit: Gerät so einstellen, dass es ohne neuen Befehl nach einigen Minuten in den Normalbetrieb fällt
// (Timeout), sonst bleibt bei einem Ausfall von Node-RED der letzte Befehl stehen.

const b = msg.befehl;

// ▼▼▼ Hier den Befehl in Register/Anfrage des Geräts übersetzen ▼▼▼
const anfrage = null; // z. B. { payload: { value: b.max_laden_W, fc: 6, unitid: 1, address: 1234, quantity: 1 } }
// ▲▲▲

if (!anfrage) {
    if (!context.get('gewarnt')) {
        context.set('gewarnt', true);
        node.warn(`Befehl für ${GERAET} kann nicht gesendet werden: Adapter noch nicht umgesetzt`);
    }
    node.status({ fill: 'yellow', shape: 'ring', text: 'Adapter noch nicht umgesetzt' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: JSON.stringify(b).slice(0, 60) });
return anfrage;

const GERAET = 'wp';
// VORLAGE – Adapter: Messwerte lesen (GERAET steht in der ersten Zeile)
// Hier wird beim Hackathon das echte Gerät angebunden. Siehe docs/geraete-adapter.md.
//
// Aufgabe: das Gerät abfragen (vorgeschaltet: HTTP-, Modbus- oder MQTT-Knoten) und die Werte in das
// einheitliche Format bringen. Ausgang → Link „→ Messwerte“:
//   msg.geraet = GERAET
//   msg.quelle = 'geraet'
//   msg.payload = { … } mit genau diesen Feldern (fehlende weglassen):
//     pv:       { leistung_W }                                   (≥ 0)
//     bkw:      { leistung_W, soc_pct? }                         Balkonkraftwerk: AC-Abgabe ≥ 0, Akku-SoC falls vorhanden
//     netz:     { bezug_W }                                      (> 0 Bezug, < 0 Einspeisung)
//     batterie: { soc_pct, leistung_W }                          (leistung_W > 0 Entladen, < 0 Laden)
//     wallbox:  { leistung_W, status, ampere }                   status: getrennt | angesteckt | laedt | pausiert | stoerung
//     auto:     { soc_pct }                                      (Ladestand des Autos, falls abrufbar)
//     wp:       { leistung_W, status, aussen_C?, raum_C? }       status: aus | heizen | warmwasser | stoerung
//
// Solange <GERÄT>_QUELLE nicht "geraet" ist, tut dieser Knoten nichts.

const QUELLE_VAR = { pv: 'PV_QUELLE', bkw: 'BKW_QUELLE', netz: 'NETZ_QUELLE', batterie: 'BATTERIE_QUELLE', wallbox: 'WALLBOX_QUELLE',
    auto: 'AUTO_QUELLE', wp: 'WP_QUELLE' }[GERAET];
if ((env.get(QUELLE_VAR) || 'simulator') !== 'geraet') {
    node.status({ fill: 'grey', shape: 'ring', text: 'nicht aktiv (' + QUELLE_VAR + ' ≠ geraet)' });
    return null;
}

// ▼▼▼ Hier die Antwort des Geräts (msg.payload) umrechnen ▼▼▼
const roh = msg.payload;
const werte = null; // z. B. { leistung_W: roh.P_PV }
// ▲▲▲

if (!werte) {
    if (!context.get('gewarnt')) {
        context.set('gewarnt', true);
        node.warn(`${QUELLE_VAR}=geraet, aber der Adapter für ${GERAET} ist noch nicht umgesetzt`);
    }
    node.status({ fill: 'yellow', shape: 'ring', text: 'Adapter noch nicht umgesetzt' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: JSON.stringify(werte).slice(0, 60) });
return { geraet: GERAET, quelle: 'geraet', payload: werte };

// Strompreise abfragen: Day-Ahead DE-LU von Energy-Charts (Fraunhofer ISE, CC BY 4.0, ohne Anmeldung)
// ─ Eingang: Inject stündlich und beim Start
// ─ Ausgang 1: msg.url für den HTTP-Knoten (heute bis übermorgen; die Preise für morgen kommen gegen 13 Uhr)
// ─ Umgebung: PREIS_ZONE (DE-LU)

const tag = t => new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin' }).format(t);
const jetzt = Date.now();
const zone = env.get('PREIS_ZONE') || 'DE-LU';
msg.url = `https://api.energy-charts.info/price?bzn=${encodeURIComponent(zone)}&start=${tag(jetzt)}&end=${tag(jetzt + 2 * 86400000)}`;
return msg;

// Strompreise auswerten
// ─ Eingang: Antwort von Energy-Charts { unix_seconds: [...], price: [...] (EUR/MWh) }
// ─ Ausgang 1: InfluxDB-Punkte (Bucket markt, Messreihe "strompreis": boerse_ct, preis_ct je Viertelstunde)
// ─ Ausgang 2: msg.log bei Fehlern
// ─ Umgebung: ABGABEN_CT (18): Netzentgelt, Steuern, Umlagen, Marge; der Endpreis ist Börse + ABGABEN_CT
// ─ Kontext: global.abbild['markt.preise'] = Stundenpreise ab der laufenden Stunde [{ t, ct }] (Endpreis),
//            global.abbild['markt.preise_15'] = Viertelstunden [{ t, ct }]

const p = msg.payload;
if (!p || !Array.isArray(p.unix_seconds) || !Array.isArray(p.price) || !p.unix_seconds.length) {
    node.status({ fill: 'red', shape: 'dot', text: 'keine Preise (HTTP ' + msg.statusCode + ')' });
    return [null, { log: { stufe: 'warnung', bereich: 'preise', text: 'Strompreise nicht abrufbar (HTTP ' + msg.statusCode + ')' } }];
}
const abgaben = parseFloat(env.get('ABGABEN_CT'));
const aufschlag = isNaN(abgaben) ? 18 : abgaben;

const viertel = [];
const punkte = [];
p.unix_seconds.forEach((s, i) => {
    const boerse = p.price[i];
    if (typeof boerse !== 'number') return;
    const t = s * 1000;
    const ct = +(boerse / 10 + aufschlag).toFixed(3);
    viertel.push({ t, ct });
    punkte.push({ measurement: 'strompreis', tags: { quelle: 'energy-charts' },
        fields: { boerse_ct: +(boerse / 10).toFixed(3), preis_ct: ct }, timestamp: new Date(t) });
});

// Stundenmittel ab der laufenden Stunde (die Regelung rechnet stündlich wie in Haus-EMS)
const stunden = {};
for (const v of viertel) {
    const h = Math.floor(v.t / 3600000) * 3600000;
    (stunden[h] = stunden[h] || []).push(v.ct);
}
const ab = Math.floor(Date.now() / 3600000) * 3600000;
const liste = Object.keys(stunden).map(Number).sort((a, b) => a - b).filter(h => h >= ab)
    .map(h => ({ t: h, ct: +(stunden[h].reduce((a, b) => a + b, 0) / stunden[h].length).toFixed(2) }));

const abbild = global.get('abbild') || {};
const jetzt = Date.now();
abbild['markt.preise'] = { wert: liste, einheit: 'ct/kWh', zeit: jetzt, quelle: 'energy-charts' };
abbild['markt.preise_15'] = { wert: viertel.filter(v => v.t >= ab), einheit: 'ct/kWh', zeit: jetzt, quelle: 'energy-charts' };
if (liste.length) abbild['markt.preis_jetzt_ct'] = { wert: liste[0].ct, einheit: 'ct/kWh', zeit: jetzt, quelle: 'energy-charts' };
global.set('abbild', abbild);

const bis = liste.length ? new Date(liste[liste.length - 1].t).toLocaleString('de-DE', { timeZone: 'Europe/Berlin', weekday: 'short', hour: '2-digit' }) : '–';
node.status({ fill: 'green', shape: 'dot', text: `${liste.length} h bekannt, bis ${bis} Uhr · jetzt ${liste.length ? liste[0].ct.toFixed(1) : '–'} ct` });
return [{ payload: punkte }, null];

// PV-Prognose abfragen: Open-Meteo, Einstrahlung auf die geneigte Modulfläche (ohne Anmeldung)
// ─ Eingang: Inject stündlich und beim Start
// ─ Ausgang 1: je Dachfläche eine Nachricht mit msg.url und msg.flaeche, mit msg.parts für den Join-Knoten
// ─ Umgebung: STANDORT_LAT, STANDORT_LON,
//             PV_FLAECHEN = "Neigung/Azimut/kWp;…", Azimut wie Open-Meteo: 0 = Süd, -90 = Ost, 90 = West
//             Beispiel: "35/-90/4.5;35/90/4.5" (Ost-West-Dach mit je 4,5 kWp). Standard: "30/0/8"
//             BKW_FLAECHEN wie PV_FLAECHEN für das Balkonkraftwerk (nur wenn BKW_QUELLE ≠ aus), z. B. "90/0/0.8"

const lat = parseFloat(env.get('STANDORT_LAT')) || 51.16; // ohne Einstellung: Mitte Deutschlands (Warnung beim Start)
const lon = parseFloat(env.get('STANDORT_LON')) || 10.45;
const lesen = (text, art) => String(text || '').split(';')
    .map(s => s.trim()).filter(Boolean)
    .map(s => { const [neigung, azimut, kwp] = s.split('/').map(parseFloat); return { neigung, azimut, kwp, art }; })
    .filter(f => [f.neigung, f.azimut, f.kwp].every(x => !isNaN(x)));
const flaechen = lesen(env.get('PV_FLAECHEN') || '30/0/8', 'anlage')
    .concat((env.get('BKW_QUELLE') || 'aus') !== 'aus' ? lesen(env.get('BKW_FLAECHEN'), 'bkw') : []);
if (!flaechen.length) {
    node.status({ fill: 'red', shape: 'dot', text: 'PV_FLAECHEN ungültig' });
    return null;
}
const id = 'prognose-' + Date.now();
node.status({ fill: 'blue', shape: 'dot', text: `${flaechen.length} Fläche(n), ${flaechen.reduce((a, f) => a + f.kwp, 0)} kWp` });
return [flaechen.map((f, i) => ({
    flaeche: f,
    url: `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}` +
         `&hourly=global_tilted_irradiance,temperature_2m&tilt=${f.neigung}&azimuth=${f.azimut}` +
         `&past_days=1&forecast_days=2&timeformat=unixtime&timezone=UTC`,
    parts: { id, index: i, count: flaechen.length, type: 'array' },
}))];

// Antwort und Dachfläche zusammenpacken, damit „Prognose auswerten“ die kWp kennt
msg.payload = { antwort: msg.payload, flaeche: msg.flaeche };
return msg;

// PV-Prognose auswerten
// ─ Eingang: msg.payload = [{ antwort, flaeche }, …] vom Join-Knoten, eine je Dachfläche
//            (der Knoten "Fläche anhängen" packt Open-Meteo-Antwort und Fläche mit kWp zusammen)
// ─ Ausgang 1: InfluxDB-Punkte (Bucket markt, Messreihe "pv_prognose": leistung_W je Stunde)
// ─ Ausgang 2: msg.log bei Fehlern
// ─ Umgebung: PV_PR (Performance Ratio, 0,85): Verluste durch Wechselrichter, Kabel, Wärme, Verschmutzung
//             BKW_MAX_W (800): Abgabe des Balkonkraftwerks ist gesetzlich begrenzt, die Prognose wird gekappt
// ─ Kontext: global.abbild['prognose.pv'] = [{ t (Beginn der Stunde), W }] gesamt (Anlage + Balkonkraftwerk),
//            dazu 'prognose.pv_anlage' und 'prognose.bkw' getrennt (für den Simulator und Grafana)
// Open-Meteo gibt Strahlung als Mittel der VORANGEGANGENEN Stunde an: der Wert mit Zeitstempel t gilt für t-1h … t.

const pr = parseFloat(env.get('PV_PR')) || 0.85;
const antworten = Array.isArray(msg.payload) ? msg.payload : [];
const summe = { anlage: {}, bkw: {} };
let ok = 0;
for (const a of antworten) {
    const h = a && a.antwort && a.antwort.hourly;
    if (!h || !Array.isArray(h.time)) continue;
    ok++;
    h.time.forEach((s, i) => {
        const gti = h.global_tilted_irradiance[i];
        if (typeof gti !== 'number') return;
        const t = (s - 3600) * 1000;
        const art = a.flaeche.art === 'bkw' ? 'bkw' : 'anlage';
        summe[art][t] = (summe[art][t] || 0) + gti * a.flaeche.kwp * pr; // W/m² × kWp = W bei 1000 W/m² Normstrahlung
    });
}
if (!ok) {
    node.status({ fill: 'red', shape: 'dot', text: 'keine Prognose' });
    return [null, { log: { stufe: 'warnung', bereich: 'prognose', text: 'PV-Prognose nicht abrufbar' } }];
}
const bkwMax = parseFloat(env.get('BKW_MAX_W')) || 800;
const zeiten = [...new Set([...Object.keys(summe.anlage), ...Object.keys(summe.bkw)])].map(Number).sort((a, b) => a - b);
const teile = zeiten.map(t => {
    const anlage = Math.round(summe.anlage[t] || 0), bkw = Math.round(Math.min(bkwMax, summe.bkw[t] || 0));
    return { t, anlage, bkw, W: anlage + bkw };
});
const liste = teile.map(x => ({ t: x.t, W: x.W }));
const abbild = global.get('abbild') || {};
const jetztMs = Date.now();
abbild['prognose.pv'] = { wert: liste, einheit: 'W', zeit: jetztMs, quelle: 'open-meteo' };
abbild['prognose.pv_anlage'] = { wert: teile.map(x => ({ t: x.t, W: x.anlage })), einheit: 'W', zeit: jetztMs, quelle: 'open-meteo' };
abbild['prognose.bkw'] = { wert: teile.map(x => ({ t: x.t, W: x.bkw })), einheit: 'W', zeit: jetztMs, quelle: 'open-meteo' };
global.set('abbild', abbild);

const ab = Math.floor(Date.now() / 3600000) * 3600000;
const heute = liste.filter(x => x.t >= ab && x.t < ab + 24 * 3600000).reduce((a, x) => a + x.W, 0);
node.status({ fill: 'green', shape: 'dot', text: `${ok} Fläche(n) · nächste 24 h ${(heute / 1000).toFixed(1)} kWh` });
return [{ payload: teile.map(x => ({ measurement: 'pv_prognose', tags: { quelle: 'open-meteo' },
    fields: { leistung_W: x.W, anlage_W: x.anlage, bkw_W: x.bkw }, timestamp: new Date(x.t) })) }, null];

// Wetter abfragen: Open-Meteo am Standort (ohne Anmeldung)
// ─ Eingang: msg.topic = 'aktuell' (alle 10 min) oder 'verlauf' (beim Start: Stundenwerte der letzten 48 h)
// ─ Ausgang 1: msg.url für den HTTP-Knoten
// ─ Umgebung: STANDORT_LAT, STANDORT_LON, STANDORT_HOEHE (m, optional)

const lat = parseFloat(env.get('STANDORT_LAT')) || 51.16; // ohne Einstellung: Mitte Deutschlands (Warnung beim Start)
const lon = parseFloat(env.get('STANDORT_LON')) || 10.45;
const hoehe = parseFloat(env.get('STANDORT_HOEHE'));
const VARS = 'temperature_2m,relative_humidity_2m,apparent_temperature,dew_point_2m,precipitation,rain,snowfall,' +
    'weather_code,cloud_cover,pressure_msl,surface_pressure,wind_speed_10m,wind_direction_10m,wind_gusts_10m';
const basis = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}` +
    (isNaN(hoehe) ? '' : `&elevation=${hoehe}`) + '&timeformat=unixtime&wind_speed_unit=kmh';
msg.url = msg.topic === 'verlauf'
    ? `${basis}&hourly=${VARS}&past_days=2&forecast_days=1`
    : `${basis}&current=${VARS},is_day&forecast_days=1`;
return msg;

// Wetter auswerten
// ─ Eingang: Open-Meteo-Antwort mit "current" (aktuell) oder "hourly" (Verlauf 48 h)
// ─ Ausgang 1: InfluxDB-Punkte (Bucket markt, Messreihe "wetter")
// ─ Kontext: global.abbild['wetter.temperatur_C'] und weitere Felder (nur aus "current")
// Felder wie im ersten Wetter-Flow: temperatur, gefuehlt, taupunkt, luftfeuchte, niederschlag, regen, schnee,
// wettercode, bewoelkung, luftdruck, luftdruck_ort, wind, windrichtung, boeen, tag

const MAP = {
    temperature_2m: 'temperatur', apparent_temperature: 'gefuehlt', dew_point_2m: 'taupunkt',
    relative_humidity_2m: 'luftfeuchte', precipitation: 'niederschlag', rain: 'regen', snowfall: 'schnee',
    weather_code: 'wettercode', cloud_cover: 'bewoelkung', pressure_msl: 'luftdruck',
    surface_pressure: 'luftdruck_ort', wind_speed_10m: 'wind', wind_direction_10m: 'windrichtung',
    wind_gusts_10m: 'boeen', is_day: 'tag',
};
const TAGS = { ort: env.get('STANDORT_NAME') || 'Standort', quelle: 'open-meteo' };
const p = msg.payload || {};
const punkte = [];

if (p.current) {
    const c = p.current, fields = {};
    for (const [von, nach] of Object.entries(MAP)) if (typeof c[von] === 'number') fields[nach] = c[von];
    punkte.push({ measurement: 'wetter', tags: TAGS, fields, timestamp: new Date(c.time * 1000) });
    const abbild = global.get('abbild') || {};
    const zeit = Date.now();
    abbild['wetter.temperatur_C'] = { wert: fields.temperatur, einheit: '°C', zeit, quelle: 'open-meteo' };
    abbild['wetter.bewoelkung_pct'] = { wert: fields.bewoelkung, einheit: '%', zeit, quelle: 'open-meteo' };
    abbild['wetter.wettercode'] = { wert: fields.wettercode, einheit: '', zeit, quelle: 'open-meteo' };
    global.set('abbild', abbild);
    node.status({ fill: 'green', shape: 'dot', text: `${fields.temperatur} °C, ${fields.luftfeuchte} % – ${new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin' })}` });
} else if (p.hourly && Array.isArray(p.hourly.time)) {
    const jetzt = Date.now() / 1000;
    p.hourly.time.forEach((t, i) => {
        if (t > jetzt) return; // keine Vorhersage speichern
        const fields = {};
        for (const [von, nach] of Object.entries(MAP)) {
            const v = p.hourly[von] && p.hourly[von][i];
            if (typeof v === 'number') fields[nach] = v;
        }
        if (Object.keys(fields).length) punkte.push({ measurement: 'wetter', tags: TAGS, fields, timestamp: new Date(t * 1000) });
    });
    node.status({ fill: 'blue', shape: 'dot', text: `Verlauf: ${punkte.length} Stundenwerte` });
} else {
    node.status({ fill: 'red', shape: 'dot', text: 'keine Wetterdaten (HTTP ' + msg.statusCode + ')' });
    return null;
}
msg.payload = punkte;
return msg;

// 🧪 Simulator (alle 10 s): bildet PV, Batterie, Wallbox mit Auto und Wärmepumpe nach, solange die echten
// Geräte fehlen. Er folgt den Befehlen des EMS genau so, wie es ein echtes Gerät tun sollte.
// ─ Eingang: Inject alle 10 s
// ─ Ausgang 1: Messwerte (mehrere Nachrichten) → Link „→ Messwerte“, Quelle 'simulator'
// ─ Liest: global.befehl_batterie, global.befehl_wallbox, global.befehl_wp, global.abbild (prognose.pv, wetter.temperatur_C)
// ─ Umgebung: <GERÄT>_QUELLE (nur Geräte mit "simulator" werden simuliert), PV_FLAECHEN (kWp),
//             BATTERIE_KAPAZITAET_WH, BATTERIE_MAX_W, BATTERIE_MIN_SOC, WB_PHASEN, WB_MAX_A, WB_AKKU_KWH, SIM_ZUFALL
// Modell (bewusst einfach, Zahlen in docs/simulator.md):
//   PV        = Prognose der laufenden Stunde × Wolkenfaktor (Zufallsweg 0,5 … 1,05)
//   BKW       = Prognose des Balkonkraftwerks × Wolkenfaktor, höchstens BKW_MAX_W (nur mit BKW_QUELLE = simulator)
//   Haus      = Grundlast 250 W + Tagesprofil + gelegentliche Spitzen (Wasserkocher, Herd)
//   WP        = Gebäude mit 20 kWh/K Speicher und 0,15 kW/K Verlust; Heizlauf mit 1,8 kW el. (COP 3,5),
//               Warmwasser 6:30 und 18:30 je 30 min mit 2,2 kW; SG-Ready 3 / Anhebung hebt den Raumsollwert
//   Auto      = werktags 7:00–17:30 unterwegs (kommt mit −15 % zurück), Ladeziel im Auto 80 %
//   Batterie  = Wirkungsgrad 95 % je Richtung, folgt dem Befehl (eigenverbrauch, laden, begrenzt)
//   Netz      = Haus + WP + Wallbox − PV − Balkonkraftwerk − Batterie

const jetzt = Date.now();
const abbild = global.get('abbild') || {};
function zahl(n, std) { const v = parseFloat(env.get(n)); return isNaN(v) ? std : v; }
const sim = name => (env.get(name) || 'simulator') === 'simulator';
const stundeDez = t => {
    const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Berlin', hour: 'numeric', minute: 'numeric',
        hourCycle: 'h23', weekday: 'short' }).formatToParts(t).map(x => [x.type, x.value]));
    return { h: +p.hour + +p.minute / 60, werktag: !['Sat', 'Sun'].includes(p.weekday) };
};
const zufall = (env.get('SIM_ZUFALL') || 'an') !== 'aus' ? Math.random : () => 0.5;

const s = context.get('s') || {
    zeit: jetzt, wolke: 0.9, soc: 50, raum: 21.0, wpLaeuft: false, autoSoc: 45, autoDa: true, spitzeBis: 0, spitzeW: 0,
};
const dtH = Math.min(60, Math.max(1, (jetzt - s.zeit) / 1000)) / 3600; // Stunden seit dem letzten Schritt
s.zeit = jetzt;
const { h, werktag } = stundeDez(jetzt);

// ── PV und Balkonkraftwerk ──
function ausPrognose(signal) {
    const prog = abbild[signal];
    if (!prog || !Array.isArray(prog.wert)) return 0;
    const h0 = Math.floor(jetzt / 3600000) * 3600000;
    const a = prog.wert.find(x => x.t === h0), b = prog.wert.find(x => x.t === h0 + 3600000);
    return a ? (b ? a.W + (b.W - a.W) * ((jetzt - h0) / 3600000) : a.W) : 0;
}
s.wolke = Math.min(1.05, Math.max(0.5, s.wolke + (zufall() - 0.5) * 0.08));
const pv = Math.max(0, Math.round((abbild['prognose.pv_anlage'] ? ausPrognose('prognose.pv_anlage') : ausPrognose('prognose.pv')) * s.wolke));
const simBkw = (env.get('BKW_QUELLE') || 'aus') === 'simulator';
const bkw = simBkw ? Math.max(0, Math.round(Math.min(zahl('BKW_MAX_W', 800), ausPrognose('prognose.bkw') * s.wolke))) : 0;

// ── Haus (ohne WP und Wallbox) ──
let haus = 250 + 50 * Math.sin(h / 24 * 2 * Math.PI);
if (h >= 6.5 && h < 8.5) haus += 400;
if (h >= 11.5 && h < 13) haus += 500;
if (h >= 17 && h < 22) haus += 600;
if (jetzt > s.spitzeBis && zufall() < 0.004) { s.spitzeBis = jetzt + (60 + zufall() * 240) * 1000; s.spitzeW = 1500 + zufall() * 1500; }
if (jetzt < s.spitzeBis) haus += s.spitzeW;
haus = Math.round(haus + (zufall() - 0.5) * 80);

// ── Wärmepumpe ──
const aussenE = abbild['wetter.temperatur_C'];
const aussen = aussenE && typeof aussenE.wert === 'number' ? aussenE.wert : 5;
const bwp = global.get('befehl_wp') || {};
const anhebung = typeof bwp.anhebung_K === 'number' ? bwp.anhebung_K : (bwp.sgready === 3 ? 1.5 : 0);
const raumSoll = 21 + anhebung;
const ww = (h >= 6.5 && h < 7) || (h >= 18.5 && h < 19);
let wpW = 0, wpStatus = 'aus';
if (sim('WP_QUELLE')) {
    if (aussen < 15) {
        if (!s.wpLaeuft && s.raum < raumSoll - 0.3) s.wpLaeuft = true;
        if (s.wpLaeuft && s.raum > raumSoll + 0.3) s.wpLaeuft = false;
    } else s.wpLaeuft = false;
    let waerme = 0;
    if (ww) { wpW = 2200; wpStatus = 'warmwasser'; }
    else if (s.wpLaeuft) { wpW = 1800; wpStatus = 'heizen'; waerme = 1.8 * 3.5; }
    s.raum += (waerme - 0.15 * (s.raum - aussen)) * dtH / 20;
    wpW = Math.round(wpW * (0.95 + zufall() * 0.1));
}

// ── Auto und Wallbox ──
const bwb = global.get('befehl_wallbox') || { modus: 'frei' };
const phasen = zahl('WB_PHASEN', 3), maxA = zahl('WB_MAX_A', 16), akkuKWh = zahl('WB_AKKU_KWH', 60);
let wbW = 0, wbStatus = 'getrennt';
if (sim('WALLBOX_QUELLE')) {
    const unterwegs = werktag && h >= 7 && h < 17.5;
    if (s.autoDa && unterwegs) s.autoDa = false;
    if (!s.autoDa && !unterwegs) { s.autoDa = true; s.autoSoc = Math.max(5, s.autoSoc - 15 - zufall() * 10); }
    if (s.autoDa) {
        wbStatus = 'angesteckt';
        if (bwb.modus === 'pause') wbStatus = 'pausiert';
        else if (s.autoSoc < 80) {
            const a = bwb.modus === 'strom' ? Math.min(maxA, bwb.ampere || 6) : maxA;
            wbW = Math.round(a * 230 * phasen * (0.97 + zufall() * 0.03));
            wbStatus = 'laedt';
            s.autoSoc = Math.min(80, s.autoSoc + wbW / 1000 * dtH * 0.9 / akkuKWh * 100);
        }
    }
}

// ── Batterie ──
const cap = zahl('BATTERIE_KAPAZITAET_WH', 10000), maxW = zahl('BATTERIE_MAX_W', 5000), socMin = zahl('BATTERIE_MIN_SOC', 10);
const bb = global.get('befehl_batterie') || { modus: 'eigenverbrauch' };
const befehlAlt = !bb.zeit || jetzt - bb.zeit > 5 * 60000; // Timeout: ohne neuen Befehl zurück in den Eigenverbrauch
const modus = befehlAlt ? 'eigenverbrauch' : bb.modus;
const bedarf = haus + wpW + wbW - pv - bkw; // > 0 Defizit, < 0 Überschuss
let batt = 0; // > 0 Entladen, < 0 Laden
if (sim('BATTERIE_QUELLE')) {
    if (modus === 'laden') batt = -Math.min(maxW, bb.leistung_W || maxW);
    else {
        batt = Math.max(-maxW, Math.min(maxW, bedarf));
        if (modus === 'begrenzt') {
            if (batt > 0 && typeof bb.max_entladen_W === 'number') batt = Math.min(batt, bb.max_entladen_W);
            if (batt < 0 && typeof bb.max_laden_W === 'number') batt = Math.max(batt, -bb.max_laden_W);
        }
    }
    if (batt > 0 && s.soc <= socMin) batt = 0;
    if (batt < 0 && s.soc >= 100) batt = 0;
    const wh = batt > 0 ? batt * dtH / 0.95 : batt * dtH * 0.95;
    s.soc = Math.min(100, Math.max(0, s.soc - wh / cap * 100));
    batt = Math.round(batt);
}
const netz = Math.round(haus + wpW + wbW - pv - bkw - batt);
context.set('s', s);

const msgs = [];
const m = (geraet, quelleVar, payload) => { if (sim(quelleVar)) msgs.push({ geraet, quelle: 'simulator', payload, zeit: jetzt }); };
m('pv', 'PV_QUELLE', { leistung_W: pv });
if (simBkw) msgs.push({ geraet: 'bkw', quelle: 'simulator', payload: { leistung_W: bkw }, zeit: jetzt });
m('batterie', 'BATTERIE_QUELLE', { soc_pct: +s.soc.toFixed(1), leistung_W: batt, modus });
m('wallbox', 'WALLBOX_QUELLE', { leistung_W: wbW, status: wbStatus, ampere: wbW ? Math.round(wbW / 230 / phasen) : 0 });
m('auto', 'AUTO_QUELLE', { soc_pct: +s.autoSoc.toFixed(1) });
m('wp', 'WP_QUELLE', { leistung_W: wpW, status: wpStatus, raum_C: +s.raum.toFixed(2), aussen_C: aussen });
m('netz', 'NETZ_QUELLE', { bezug_W: netz }); // zuletzt, damit die Hausbilanz alle Werte dieses Schritts sieht
node.status({ fill: 'blue', shape: 'dot',
    text: `PV ${pv}${simBkw ? ' + BKW ' + bkw : ''} · Haus ${haus} · WP ${wpW} · Auto ${wbW} (${Math.round(s.autoSoc)} %) · Akku ${batt} (${s.soc.toFixed(0)} %) · Netz ${netz} W` });
return [msgs];
